    """seg is a run of chars all <=0xFF (latin1-encodable). Try to recover original utf-8/sjis text."""
    if not seg:
        return seg
    b = seg.encode('latin-1')
    for enc in ('utf-8', 'cp932', 'shift_jis'):
        try:
            out = b.decode(enc)
            # sanity: if decoding produced replacement-ish or same thing with mostly ascii unreadable, still accept utf-8 first success
            return out
        except Exception:
            continue
    return seg  # give up, leave as-is

def fix(s):
    if not s:
        return s
    # split into runs of latin1-encodable (<=0xFF) vs not
    parts = []
    buf = []
    buf_is_latin1 = None
    for ch in s:
        is_latin1 = ord(ch) <= 0xFF
        if buf_is_latin1 is None:
            buf_is_latin1 = is_latin1
        if is_latin1 == buf_is_latin1:
            buf.append(ch)
        else:
            parts.append((buf_is_latin1, ''.join(buf)))
            buf = [ch]
            buf_is_latin1 = is_latin1
    if buf:
